      undefined,
      h.ctx,
    );
    const dir = h.entries.at(-1)!.data.artifactDir;

    for (let round = 1; round <= 3; round++) {
      await h.events.get("tool_result")({
        toolName: "subagent", toolCallId: `builder-${round}`, input: { agent: "builder" },
