import { mkdtempSync, writeFileSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it, beforeEach, afterEach } from "vitest";
import { taskMode } from "../extensions/workflow/modes/task.ts";

async function createHarness(tmp: string) {
  const { __resetWorkflowRegistryForTests, createWorkflowExtension } = await import("../extensions/workflow/adapter.ts");
  __resetWorkflowRegistryForTests();
  const events = new Map<string, any>();
  const eventHandlers = new Map<string, any[]>();
  const tools = new Map<string, any>();
  const entries: any[] = [];
  const sent: any[] = [];
  const notifies: any[] = [];
  const pi: any = {
    on(n: string, h: any) {
      events.set(n, h);
      const arr = eventHandlers.get(n) ?? [];
      arr.push(h);
      eventHandlers.set(n, arr);
    },
    registerTool(t: any) { tools.set(t.name, t); },
    registerCommand() {},
    appendEntry(_ct: string, d: any) { entries.push(d); },
    sendUserMessage(t: string, o?: any) { sent.push({t,o}); },
    exec: async () => ({ code: 0, stdout: "commit\n", stderr: "" }),
  };
  const ctx: any = {
    isIdle: () => false,
    hasUI: false,
    ui: { notify(t: string,l: string){notifies.push({t,l});}, setStatus(){}, theme:{fg:(_:string,t:string)=>t} },
  };
  createWorkflowExtension(taskMode.config, taskMode)(pi);
  return { pi, events, eventHandlers, tools, entries, sent, notifies, ctx };
}

describe("debug resume", () => {
  let tmp = "";
  beforeEach(() => { tmp = mkdtempSync(join(tmpdir(), "debug-")); });
  afterEach(() => { if (tmp) rmSync(tmp, {recursive:true, force:true}); });

  it("dumps resume behavior", async () => {
    process.chdir(tmp);
    const h = await createHarness(tmp);
    await h.tools.get("start_task_workflow").execute("start", { goal: "build X" }, undefined, undefined, h.ctx);
    const dir = h.entries.at(-1).artifactDir;
    const statePath = join(dir, "workflow.json");
    writeFileSync(join(dir, "plan.md"), "# Plan\nWORKFLOW_PLAN_STATUS: ready");
    writeFileSync(join(dir, "reuse.md"), "skip");
    writeFileSync(join(dir, "handoff.md"), "# Handoff\nWORKFLOW_HANDOFF_STATUS: ready");

    const before = JSON.parse(readFileSync(statePath, "utf8"));
    console.log("BEFORE", before.phase, "autoArmed", before.autoArmed);

    const { createWorkflowExtension, __resetWorkflowRegistryForTests } = await import("../extensions/workflow/adapter.ts");
    __resetWorkflowRegistryForTests();
    createWorkflowExtension(taskMode.config, taskMode)(h.pi);

    const resumed = await h.tools.get("resume_task_workflow").execute("resume", { run: before.id }, undefined, undefined, h.ctx);
    console.log("RESUME result", resumed.details);
    const after = JSON.parse(readFileSync(statePath, "utf8"));
    console.log("AFTER", after.phase, "autoArmed", after.autoArmed);
    console.log("sent count", h.sent.length);
    for (const s of h.sent) console.log("SENT", s.t?.slice(0,80));
  });
});
