  };
  const ctx: any = { isIdle: () => false, hasUI: false, ui: { notify(){}, setStatus(){}, theme:{fg:(_:string,t:string)=>t} } };
  createWorkflowExtension(taskMode.config, taskMode)(pi);
  return { tools, entries, sent, ctx, pi };
}

