    const resumed = await h.tools.get("resume_task_workflow").execute("resume", { run: JSON.parse(readFileSync(statePath, "utf8")).id }, undefined, undefined, h.ctx);
    console.log("RESUME", resumed.details);

    // Now check the saved state after resume and see if onArtifactMaybe would advance further
    const after = JSON.parse(readFileSync(statePath, "utf8"));
    console.log("AFTER", after.phase, after.autoArmed);
  });
});
